const setLivestockQuantity = `-- name: SetLivestockQuantity :exec
UPDATE livestock_entries SET current_quantity = $1, updated_at = $2
WHERE id = $3
`

type SetLivestockQuantityParams struct {
	CurrentQuantity int32
	Now             time.Time
	ID              uuid.UUID
}

// Run with the entry locked, after the service checked every running balance. version is
// not bumped: it covers the description, which a concurrent PATCH may change.
func (q *Queries) SetLivestockQuantity(ctx context.Context, arg SetLivestockQuantityParams) error {
	_, err := q.db.Exec(ctx, setLivestockQuantity, arg.CurrentQuantity, arg.Now, arg.ID)
	return err
}

const updateLivestockEntry = `-- name: UpdateLivestockEntry :execrows
UPDATE livestock_entries
SET species_id = $1, category = $2, coral_type = $3,
    display_name = $4, form = $5, quarantine_status = $6,
    location_note = $7, source_note = $8, notes = $9,
    updated_at = $10, version = version + 1
WHERE id = $11 AND version = $12
`

type UpdateLivestockEntryParams struct {
	SpeciesID        *uuid.UUID
	Category         string
	CoralType        *string
	DisplayName      string
	Form             *string
	QuarantineStatus *string
	LocationNote     *string
	SourceNote       *string
	Notes            *string
	Now              time.Time
	ID               uuid.UUID
	Version          int32
}

func (q *Queries) UpdateLivestockEntry(ctx context.Context, arg UpdateLivestockEntryParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateLivestockEntry,
		arg.SpeciesID,
		arg.Category,
		arg.CoralType,
		arg.DisplayName,
		arg.Form,
		arg.QuarantineStatus,
		arg.LocationNote,
		arg.SourceNote,
		arg.Notes,
		arg.Now,
		arg.ID,
		arg.Version,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
